// The one job here is to end up with a list of domains, and to say
// exactly what came back when it cannot. Silent empties are what made
// the last three attempts impossible to debug.
const cfg = $('Config').first().json;
if (cfg.domains && cfg.domains.length) {
  return cfg.domains.map(domain => ({ json: { domain } }));
}
const j = $input.first().json;
const rows = j.companies || j.results || j.items || j.data || [];
const clean = d => String(d || '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const domains = [...new Set(rows
  .map(r => clean(r.domain || r.website || r.company_domain || r.companyWebsite ||
                  r.company_website || r.url))
  .filter(d => d.includes('.')))];
if (!domains.length) {
  throw new Error('No company domains in the Explee response. Top-level keys: ' +
    Object.keys(j).join(', ') + '. First row: ' +
    JSON.stringify(rows[0] || j).slice(0, 400));
}
console.log(domains.length + ' companies: ' + domains.join(', '));
return domains.map(domain => ({ json: { domain } }));

// Explee first, LinkFinder second.
//
// Explee matches job titles semantically against the campaign's target
// roles, so it answers "who at this company is my buyer". LinkFinder's
// company_domain_to_employees takes a seniority bucket instead: a live
// call on demos.fr returned a Technical Director based in Russia and a
// CFO — real directors, not the people this campaign is for.
//
// The trade is cost. Explee returns profiles without addresses at 1
// credit each, so every one of them goes through email resolution
// downstream. LinkFinder bundles the email into its 1 credit when it
// has one. Precision is worth more than that on cold email.
const cfg = $('Config').first().json;
if (!this.helpers || !this.helpers.httpRequest) {
  throw new Error('This n8n has no this.helpers.httpRequest in Code nodes.');
}
const http = opts => this.helpers.httpRequest(opts);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const LF = 'https://api.linkfinderai.com';
const hasExplee = cfg.explee_key && !cfg.explee_key.startsWith('PUT_');
const hasLf = cfg.linkfinder_key && !cfg.linkfinder_key.startsWith('PUT_');
if (!hasExplee && !hasLf) throw new Error('No Explee or LinkFinder key in Config.');

// Explee: the roles this campaign actually wants, matched semantically.
async function explee(domain) {
  if (!hasExplee) return [];
  try {
    const x = await http({ method: 'POST', json: true,
      url: 'https://api.explee.com/public/api/v1/search/people-by-domains',
      headers: { 'X-API-Key': cfg.explee_key },
      body: { domains: [domain],
              job_titles: (cfg.job_titles || ['Founder', 'Director']).slice(0, 20),
              people_per_company: cfg.per_company } });
    return (x && (x.people || x.results || x.items)) || [];
  } catch (e) { console.log(domain + ' explee: ' + e.message); return []; }
}

// LinkFinder: always async, so post then poll the job inline. A Code
// node rather than a Wait/If loop, because that loop is what hung the
// first two versions of this flow.
async function linkfinder(domain) {
  if (!hasLf) return [];
  const auth = { Authorization: 'Bearer ' + cfg.linkfinder_key };
  let r;
  try {
    r = await http({ method: 'POST', url: LF, headers: auth, json: true, body: {
      type: 'company_domain_to_employees', input_data: domain,
      seniority: cfg.seniority, employee_count: cfg.per_company } });
  } catch (e) { console.log(domain + ' linkfinder: ' + e.message); return []; }
  for (let n = 0; r && r.job_id && !r.result && n < 8; n++) {
    await sleep(8000);
    try { r = await http({ method: 'GET', headers: auth, json: true,
      url: r.poll_url || LF + '/status/' + r.job_id }); }
    catch (e) { console.log(domain + ' poll: ' + e.message); return []; }
  }
  return (r && r.result) || [];
}

const out = [];
for (const { json: { domain } } of $input.all()) {
  let rows = await explee(domain);
  let via = 'explee';
  if (!rows.length) { rows = await linkfinder(domain); via = 'linkfinder'; }
  console.log(domain + ': ' + rows.length + ' from ' + (rows.length ? via : 'neither'));
  for (const p of rows.slice(0, cfg.per_company)) out.push({ ...p, source: via });
  await sleep(1100);
}
if (!out.length) {
  throw new Error('Neither Explee nor LinkFinder found anyone at: ' +
    $input.all().map(i => i.json.domain).join(', '));
}
return [{ json: { people: out } }];

// One item holding every person. Fan them out and normalise the two
// fields the rest of the flow reads. Nobody is dropped here — search
// returns profiles, LinkFinder turns them into addresses next.
const j = $input.first().json;
const contacts = j.people || j.results || j.items || j.contacts || [];
// Explee answers in snake_case, LinkFinder in camelCase. Read both.
if (!contacts.length) {
  throw new Error('Explee returned no people. It answered with: ' +
    JSON.stringify(j).slice(0, 400));
}
return contacts.map(c => ({ json: {
  ...c,
  email: c.email || '',
  linkedin_url: c.linkedin_url || c.linkedinUrl || c.linkedin || '',
  full_name: c.full_name || c.name ||
    [c.firstName, c.lastName].filter(Boolean).join(' '),
  first_name: c.first_name || c.firstName || '',
  job_title: c.job_title || c.jobTitle || c.title || '',
  company_name: c.company_name || c.company || '',
  company_domain: c.company_domain || c.companyWebsite || c.domain || '',
  location: c.location || c.city || c.country || '',
  // What the writer is allowed to notice. The raw row also carries NACE
  // sector scores, follower counts, photo urls and a company_geo that
  // said CN for Microsoft — noise that dilutes the signal and invites
  // the model to invent from it.
  brief: Object.fromEntries(Object.entries({
    name: c.full_name || c.name ||
      [c.firstName || c.first_name, c.lastName || c.last_name].filter(Boolean).join(' '),
    title: c.job_title || c.jobTitle || c.title,
    headline: c.headline,
    company: c.company_name || c.company,
    what_the_company_does: c.company_description,
    industry: c.company_industry || c.industry,
    company_size: c.company_size,
    where: c.city || c.location || c.geo || c.country,
  }).filter(([, v]) => v)),
} }));

// Explee returns profiles, not addresses. This is what turns them into leads:
// 10 credits from a LinkedIn URL, 7 from name + company, charged whether or
// not one comes back.
//
// n8n kills a Code node at 300s (N8N_RUNNERS_TASK_TIMEOUT). A serial loop over
// 47 leads with a 1.1s spacer and an occasional 8s job poll blows that easily,
// so this works to a wall-clock budget with a few lookups in flight at once,
// and returns what it has when the budget runs out rather than dying with
// nothing. Raising the cap or the concurrency past the plan's requests/second
// is how you trade credits for 429s — the defaults sit under Starter's 5/s.
const cfg = $('Config').first().json;
const leads = $input.all().map(i => i.json);
const canHttp = !!(this.helpers && this.helpers.httpRequest);
const http = opts => this.helpers.httpRequest(opts);
const sendable = () => leads.filter(l => l.email).map(json => ({ json }));

if (!canHttp || !cfg.linkfinder_key || cfg.linkfinder_key.startsWith('PUT_')) {
  return sendable();
}

const auth = { Authorization: 'Bearer ' + cfg.linkfinder_key };
const API = 'https://api.linkfinderai.com';
const sleep = ms => new Promise(r => setTimeout(r, ms));
const deadline = Date.now() + (Number(cfg.linkfinder_budget_seconds) || 240) * 1000;
const left = () => deadline - Date.now();

// Only the leads that need a lookup and give us something to look up by.
const queue = [];
for (const lead of leads) {
  if (lead.email) continue;
  const op = lead.linkedin_url
    ? { type: 'linkedin_profile_to_email', input_data: lead.linkedin_url }
    : { type: 'lead_full_name_to_email', input_data:
        [lead.full_name || lead.name, lead.company_name || lead.company]
          .filter(Boolean).join(' ') };
  if (!op.input_data) continue;
  queue.push({ lead, op });
}
const budget = queue.splice(Number(cfg.linkfinder_max) || 0);
const skippedByCap = budget.length;

let found = 0, spent = 0, stopped = '';
let next = 0;

async function worker() {
  while (next < queue.length && !stopped) {
    if (left() < 15000) { stopped = 'out of time'; break; }
    const { lead, op } = queue[next++];
    spent += op.type === 'linkedin_profile_to_email' ? 10 : 7;
    let r;
    try {
      r = await http({ method: 'POST', url: API, headers: auth, body: op,
                       json: true, timeout: Math.min(30000, left()) });
    } catch (e) {
      // 402 out of credits, 401 bad key, 429 too fast: stop, do not hammer.
      stopped = e.message;
      break;
    }
    // Any endpoint can hand back a job instead of a result if it runs long.
    // Poll only while there is budget to spare for it.
    for (let n = 0; r && r.job_id && !r.result && n < 3 && left() > 20000; n++) {
      await sleep(5000);
      try {
        r = await http({ method: 'GET', headers: auth, json: true,
                         url: r.poll_url || API + '/status/' + r.job_id });
      } catch (e) { r = null; }
    }
    const res = r && r.result;
    const email = typeof res === 'string' ? res : (res && res.email) || '';
    if (email) { lead.email = email; found++; }
    await sleep(1100);          // per worker, so ~concurrency requests/second
  }
}

const lanes = Math.max(1, Math.min(Number(cfg.linkfinder_concurrency) || 3, 5));
await Promise.all(Array.from({ length: lanes }, worker));

const done = sendable();
console.log('LinkFinder: ' + found + ' emails, ~' + spent + ' credits, ' +
  done.length + ' of ' + leads.length + ' sendable' +
  (skippedByCap ? '; ' + skippedByCap + ' past linkfinder_max' : '') +
  (stopped ? '; stopped early: ' + stopped : ''));
return done;

// Parse the model's JSON and shape one Instantly lead. The per-lead copy
// rides as custom variables, so one campaign sends a different email to
// everyone in it.
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const reply = $input.all()[i].json;
  const lead = $('LinkFinder: fill missing emails').all()[i].json;
  // The agent answers in .output; a raw chat completion in .choices.
  let text = reply.output ?? reply.choices?.[0]?.message?.content ?? '';
  if (typeof text !== 'string') text = JSON.stringify(text);
  if (text.startsWith('```')) text = text.split('```')[1].replace(/^json/, '').trim();
  let email;
  try { email = JSON.parse(text); }
  catch (e) { continue; }   // model did not return JSON — skip, do not send junk
  const full = lead.full_name || lead.name || '';
  out.push({ json: {
    email: lead.email,
    first_name: lead.first_name || full.split(' ')[0] || '',
    last_name: full.split(' ').slice(1).join(' '),
    company_name: lead.company_name || lead.company || '',
    custom_variables: {
      subject: email.subject,
      body: String(email.body).replace(/\r\n/g, '\n').replace(/\n/g, '<br>'),
    },
  } });
}
if (!out.length) throw new Error('Nothing to send — the writer returned no usable JSON.');
// Fail here rather than at the Instantly call, so the drafted emails
// above are visible and only the destination is missing.
const camp = $('Config').first().json.instantly_campaign_id;
if (!camp || camp.startsWith('PUT_')) {
  throw new Error(out.length + ' emails are written and ready. Put an Instantly ' +
    'campaign id in the Config node to add them — the id is in the campaign URL.');
}
console.log(out.length + ' leads ready for campaign ' + camp);
return out;
